/*
 * TestSemanticFloatArm.cpp
 *
 * Tests the ARM rules of the software floating point library (SemanticFloat):
 * the environment of the Arm ARM pseudocode (the flush to zero with the
 * denormal operand flag, the default NaN, the tininess before rounding, the
 * alternative half precision of the conversions) and the operations only ARM
 * has (FMULX, the reciprocal steps and estimates, FRECPX, FRINT32 / 64, FSCALE,
 * the widening multiply-add of FMLAL, the BFloat16 dot product) against the
 * vectors of tests/arm/ArmFloatVectors.inc, generated by tests/arm/tools/
 * gen_arm_float_vectors.py from an independent Python model of the pseudocode
 * (tests/arm/tools/armfp.py, checked against the Apple M4).
 *
 * Author: Elad Raz <e@eladraz.com>
 */
#include <stdio.h>
#include "xStl/types.h"
#include "xStl/os/os.h"
#include "xStl/data/string.h"
#include "xStl/except/trace.h"
#include "xStl/except/assert.h"
#include "xStl/stream/ioStream.h"
#include "xStl/../../tests/tests.h"

#include "dismount/semantics/Semantics.h"
#include "dismount/semantics/SemanticFloat.h"

typedef SemanticFloat SF;
typedef SemanticFloat::Bits FB;
typedef SemanticType::FloatFormat Format;

// The operations of the vectors, see gen_arm_float_vectors.py
enum {
    AFV_ADD, AFV_SUB, AFV_MUL, AFV_DIV, AFV_SQRT, AFV_FMA, AFV_MULX, AFV_RECIP_STEP, AFV_RSQRT_STEP, AFV_RECIP_ESTIMATE,
    AFV_RSQRT_ESTIMATE, AFV_RECIP_EXPONENT, AFV_ROUND32, AFV_ROUND64, AFV_SCALE, AFV_MAX_NUMBER, AFV_MIN_NUMBER, AFV_CONVERT,
    AFV_FMA_WIDENING, AFV_BFLOAT_DOT, AFV_TO_INTEGER, AFV_FROM_INTEGER, AFV_COMPARE_SIGNALING, AFV_ROUND_INEXACT,
    AFV_MAX, AFV_MIN
};

struct ArmFloatVector {
    uint8 m_operation;
    uint8 m_format;
    uint8 m_format2;
    uint8 m_rounding;
    uint8 m_control;
    uint64 m_a;
    uint64 m_b;
    uint64 m_c;
    uint64 m_result;
    uint8 m_flags;
};

#include "arm/ArmFloatVectors.inc"

static const ArmFloatVector gArmFloatVectors[] = {
    ARM_FLOAT_VECTORS
    { 0xFF, 0, 0, 0, 0, 0, 0, 0, 0, 0 }
};

class TestObjectTestSemanticFloatArm : public cTestObject {
public:
    TestObjectTestSemanticFloatArm() : m_failures(0) {}

    // The format of the vectors: 1 half, 2 single, 3 double
    static Format formatOf(uint id)
    {
        switch (id)
        {
        case 1: return SemanticType::FLOAT_HALF;
        case 2: return SemanticType::FLOAT_SINGLE;
        default: return SemanticType::FLOAT_DOUBLE;
        }
    }

    static uint bitsOf(uint id)
    {
        return (id == 1) ? 16 : ((id == 2) ? 32 : 64);
    }

    static SemanticOperation::RoundingMode roundingOf(uint rmode)
    {
        static const SemanticOperation::RoundingMode modes[4] = {
            SemanticOperation::ROUND_NEAREST_EVEN,
            SemanticOperation::ROUND_TOWARD_POSITIVE,
            SemanticOperation::ROUND_TOWARD_NEGATIVE,
            SemanticOperation::ROUND_TOWARD_ZERO };
        return modes[rmode & 3];
    }

    // The environment of the ARM rules (the flags of Arm64Architecture.cpp): the half precision
    // flushes by FZ16
    static SF::Environment makeEnvironment(const ArmFloatVector& v)
    {
        SF::Environment env;
        env.m_isTininessBeforeRounding = true;
        env.m_isInputFlushSignaled = true;
        env.m_isFlushInexact = false;
        env.m_isMinMaxNanSignaling = true;
        env.m_isAddendNanFirst = true;
        env.m_isHalfFlushSeparate = true;
        env.m_flushHalfToZero = (v.m_control & 2) != 0;
        env.m_rounding = roundingOf(v.m_rounding);
        const bool isFlush = (v.m_control & 1) != 0;
        env.m_flushToZero = isFlush;
        env.m_denormalsAreZero = isFlush;
        env.m_isDefaultNanNegative = false;
        env.m_nanRule = ((v.m_control & 4) != 0) ? FloatEnvironment::NAN_DEFAULT :
                                                    FloatEnvironment::NAN_SIGNALING_FIRST;
        return env;
    }

    void fail(uint index, const ArmFloatVector& v, const char* what, uint64 got, uint64 want)
    {
        fprintf(stderr, "TestSemanticFloatArm: vector %u (op %u, format %u/%u, control %x, rounding %u, "
                "a=%llx b=%llx c=%llx): %s = %llx, expected %llx\n", index, (uint)v.m_operation,
                (uint)v.m_format, (uint)v.m_format2, (uint)v.m_control, (uint)v.m_rounding,
                (unsigned long long)v.m_a, (unsigned long long)v.m_b, (unsigned long long)v.m_c, what,
                (unsigned long long)got, (unsigned long long)want);
        m_failures++;
    }

    void run(uint index, const ArmFloatVector& v)
    {
        const Format format = formatOf(v.m_format);
        SF::Environment env = makeEnvironment(v);
        uint32 flags = 0;
        const FB a(v.m_a), b(v.m_b), c(v.m_c);
        uint64 result = 0;
        switch (v.m_operation)
        {
        case AFV_ADD: result = SF::add(format, env, a, b, flags).m_low; break;
        case AFV_SUB: result = SF::subtract(format, env, a, b, flags).m_low; break;
        case AFV_MUL: result = SF::multiply(format, env, a, b, flags).m_low; break;
        case AFV_DIV: result = SF::divide(format, env, a, b, flags).m_low; break;
        case AFV_SQRT: result = SF::squareRoot(format, env, a, flags).m_low; break;
        case AFV_FMA: result = SF::multiplyAdd(format, env, a, b, c, flags).m_low; break;
        case AFV_MULX: result = SF::multiplyExtended(format, env, a, b, flags).m_low; break;
        case AFV_RECIP_STEP: result = SF::reciprocalStep(format, env, a, b, false, true, flags).m_low; break;
        case AFV_RSQRT_STEP: result = SF::reciprocalStep(format, env, a, b, true, true, flags).m_low; break;
        case AFV_RECIP_ESTIMATE: result = SF::reciprocalEstimate(format, env, a, flags).m_low; break;
        case AFV_RSQRT_ESTIMATE: result = SF::reciprocalSqrtEstimate(format, env, a, flags).m_low; break;
        case AFV_RECIP_EXPONENT: result = SF::reciprocalExponent(format, env, a, flags).m_low; break;
        case AFV_ROUND32: result = SF::roundToIntegerBounded(format, env, a, 32, flags).m_low; break;
        case AFV_ROUND64: result = SF::roundToIntegerBounded(format, env, a, 64, flags).m_low; break;
        case AFV_SCALE: result = SF::scaleByInteger(format, env, a, v.m_b, 64, flags).m_low; break;
        case AFV_MAX_NUMBER:
            result = SF::minimumMaximum(format, env, true, SemanticOperation::BEHAVIOR_MINMAX_NUMBER, a, b, flags).m_low;
            break;
        case AFV_MIN_NUMBER:
            result = SF::minimumMaximum(format, env, false, SemanticOperation::BEHAVIOR_MINMAX_NUMBER, a, b, flags).m_low;
            break;
        case AFV_MAX:
            result = SF::minimumMaximum(format, env, true, SemanticOperation::BEHAVIOR_MINMAX_PROPAGATE_NAN, a, b, flags).m_low;
            break;
        case AFV_MIN:
            result = SF::minimumMaximum(format, env, false, SemanticOperation::BEHAVIOR_MINMAX_PROPAGATE_NAN, a, b, flags).m_low;
            break;
        case AFV_CONVERT:
        {
            // The conversions don't flush by FZ16 (the half precision operand and result), the
            // alternative half precision is theirs
            const Format target = formatOf(v.m_format2);
            SF::Environment e = makeEnvironment(v);
            e.m_flushHalfToZero = false;
            e.m_isAlternativeHalf = (v.m_control & 8) != 0;
            result = SF::convert(format, target, e, a, flags).m_low;
            break;
        }
        case AFV_FMA_WIDENING:
        {
            const Format narrow = formatOf(v.m_format2);
            result = SF::multiplyAddWidening(narrow, format, env, env, a, b, c, flags).m_low;
            break;
        }
        case AFV_BFLOAT_DOT:
            result = SF::bfloatDotAdd(c, FB(v.m_a & 0xFFFF), FB((v.m_a >> 16) & 0xFFFF),
                                      FB(v.m_b & 0xFFFF), FB((v.m_b >> 16) & 0xFFFF)).m_low;
            break;
        case AFV_TO_INTEGER:
        {
            const uint width = bitsOf(v.m_format2);
            result = SF::toInteger(format, env, a, width, (v.m_control & 16) != 0,
                                   SemanticOperation::BEHAVIOR_CONVERT_SATURATE_NAN_ZERO, flags, (uint)v.m_b);
            if (width < 64)
                result &= (((uint64)1 << width) - 1);
            break;
        }
        case AFV_FROM_INTEGER:
            result = SF::fromInteger(format, env, v.m_a, bitsOf(v.m_format2), (v.m_control & 16) != 0, flags,
                                     (uint)v.m_b).m_low;
            break;
        case AFV_COMPARE_SIGNALING:
        {
            const SF::Relation relation = SF::compare(format, env, a, b, true, flags);
            result = (relation == SF::RELATION_LESS) ? 0 : ((relation == SF::RELATION_EQUAL) ? 1 :
                     ((relation == SF::RELATION_GREATER) ? 2 : 3));
            break;
        }
        default:
            return;
        }
        if (result != v.m_result)
            fail(index, v, "result", result, v.m_result);
        else if (flags != v.m_flags)
            fail(index, v, "flags", flags, v.m_flags);
    }

    virtual void test()
    {
        uint count = 0;
        for (const ArmFloatVector* v = gArmFloatVectors; v->m_operation != 0xFF; v++)
        {
            run(count, *v);
            count++;
        }
        cout << count << " ARM floating point vectors run, " << m_failures << " failures" << endl;
        TESTS_ASSERT(m_failures == 0);
    }

    // Return the name of the module
    virtual cString getName() { return __FILE__; }

private:
    uint m_failures;
};

// Instance test object
TestObjectTestSemanticFloatArm g_globalTestSemanticFloatArm;
